import re,sys
MULTI = ['<;>','::=','->',':=','=>','←↦','↦','→','∧','∨','¬','⟨','⟩']
def isid(c):
    return c.isalpha() or c.isdigit() or c in \"_'\"
def count(b):
    i=0; n=0
    while i < len(b):
        c = b[i]
        if c.isspace(): i+=1; continue
        if isid(c):
            j=i
            while j<len(b) and isid(b[j]): j+=1
            n+=1; i=j; continue
        for m in ['<;>',':=','=>','↦','→','⦃','⦄']:
            if b.startswith(m,i):
                n+=1; i+=len(m); break
        else:
